using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using GrimList.Core;

namespace GrimList.Application;

// Compatibility metadata generated by the production importer. Apply only to the
// exact source archive and base profiles; never replace user data or source values.
public static partial class EffectiveDatasheetRecovery
{
    public record UnitMetadata(string Alias, string ProfileHash, DatasheetSemantics Semantics, string? AbilitiesHash = null);
    public record CardMetadata(string Faction, string Key, string TextHash, List<DatasheetModifier> Modifiers, EnhancementCondition? Eligibility = null);
    public record Pack(string SourceHash, List<UnitMetadata> Units, List<CardMetadata> Cards, int Version = 1);
    private static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value)));
    // Version 1 metadata was generated with CRLF-formatted JSON. Pin its canonical
    // representation: System.Text.Json otherwise uses the platform's newline,
    // making Android reject identical profiles hashed on Windows.
    public static string ProfileHash(UnitProfile profile) => Hash(DataJson.Write(new { profile.Characteristics, profile.Models, profile.Weapons }).ReplaceLineEndings("\r\n"));
    private static string AbilitiesHash(UnitProfile profile) => Hash(DataJson.Write(profile.Abilities).ReplaceLineEndings("\r\n"));
    public static Pack Create(Dataset data) => new(data.Source.ContentHash,
        data.Units.Where(u => u.Profile?.Semantics is { } s && s.Choices.Count + s.Modifiers.Count + (s.Abilities?.Count ?? 0) + (s.Attachments?.Count ?? 0) > 0).SelectMany(u => (u.Aliases ?? [])
            .Where(a => a.StartsWith("bsdata:", StringComparison.Ordinal)).Select(a => new UnitMetadata(a, ProfileHash(u.Profile!), u.Profile!.Semantics!, AbilitiesHash(u.Profile!)))).ToList(),
        (data.ReferenceCards ?? []).Where(c => c.Section == "Enhancements").Select(c => new CardMetadata(c.Faction, Enhancements.Key(c), Hash(c.Text), c.Modifiers ?? [])).ToList(), 3);
    // Retain exact fingerprints for older import formats (which lacked weapon source
    // identities). Only identical source archives and ability text may share new rules.
    public static Pack Refresh(Pack generated, IEnumerable<Pack> previous)
    {
        var updated = generated.Units.ToDictionary(u => u.Alias);
        var legacy = previous.Where(p => p.SourceHash.Equals(generated.SourceHash, StringComparison.OrdinalIgnoreCase)).SelectMany(p => p.Units)
            .Select(old => updated.TryGetValue(old.Alias, out var next) && old.AbilitiesHash != null && old.AbilitiesHash == next.AbilitiesHash
                ? old with { Semantics = next.Semantics } : old);
        return generated with { Units = generated.Units.Concat(legacy).DistinctBy(u => (u.Alias, u.ProfileHash)).ToList() };
    }
    public static Dataset Apply(Dataset data, IEnumerable<Pack> packs)
    {
        var units = new Dictionary<string, UnitMetadata>(StringComparer.OrdinalIgnoreCase);
        var cards = new Dictionary<string, CardMetadata>(StringComparer.OrdinalIgnoreCase);
        foreach (var pack in packs)
        {
            foreach (var unit in pack.Units) units[pack.SourceHash + "/" + unit.Alias + "/" + unit.ProfileHash] = unit;
            foreach (var card in pack.Cards) cards[pack.SourceHash + "/" + card.Faction + "/" + card.Key] = card;
        }
        var changed = false;
        var projected = data.Units.Select(unit =>
        {
            if (unit.Profile == null || unit.ProfileSource?.ContentHash is not { Length: > 0 } hash) return unit;
            var profileHash = ProfileHash(unit.Profile);
            var metadata = (unit.Aliases ?? []).Select(a => units.GetValueOrDefault(hash + "/" + a + "/" + profileHash)).FirstOrDefault(m => m != null);
            if (metadata == null || (unit.Profile.Semantics?.Version ?? 0) >= metadata.Semantics.Version || ProfileHash(unit.Profile) != metadata.ProfileHash
                || metadata.AbilitiesHash != null && AbilitiesHash(unit.Profile) != metadata.AbilitiesHash) return unit;
            changed = true;
            // Leave base values and existing loadout declarations intact. The editor
            // hides separately persisted semantic choices from the wargear controls.
            return unit with { Profile = unit.Profile with { Semantics = metadata.Semantics } };
        }).ToList();
        var references = (data.ReferenceCards ?? []).Select(card =>
        {
            if (card.Source?.ContentHash is not { Length: > 0 } hash
                || !cards.TryGetValue(hash + "/" + card.Faction + "/" + Enhancements.Key(card), out var metadata)
                || Hash(card.Text) != metadata.TextHash) return card;
            // Effects still require matching rule content. Eligibility is owned solely
            // by EnhancementLibraryRepair's source identity/conflict policy; historical
            // effect packs must never overwrite it or recover it through a prose hash.
            var modifiers = metadata.Modifiers.Select(ModelStatModifiers.Normalize).ToList();
            if (DataJson.Write(card.Modifiers) == DataJson.Write(modifiers)) return card;
            changed = true; return card with { Modifiers = modifiers };
        }).ToList();
        return ModelStatModifiers.Repair(changed ? data with { Units = projected, ReferenceCards = references } : data);
    }
}
